import java.util.List;
import java.util.ArrayList;

public class Main {
    // Upper Bounded Wildcard: accept Number or its subclasses (Integer, Double...)
    public static double sum(List<? extends Number> list) {
        double sum = 0;
        for (Number n : list) {
            sum += n.doubleValue();
        }
        // list.add(10); // Error! Read-only (mostly)
        return sum;
    }

    public static void main(String[] args) {
        List<Integer> ints = new ArrayList<>();
        ints.add(1);
        ints.add(2);

        List<Double> doubles = new ArrayList<>();
        doubles.add(3.5);

        // Both work thanks to wildcard
        System.out.println("Sum Ints: " + sum(ints));
        System.out.println("Sum Doubles: " + sum(doubles));
    }
}
